# Hypothesis: Vertical mirror around center row (row 12)

def mirror_vertical(grid):
    r = len(grid)
    result = [[cell for cell in row] for row in grid]

    for i in range(r // 2):
        j = r - 1 - i
        # Mirror row i onto row j
        for c in range(len(grid[0])):
            result[j][c] = result[i][c]

    return result

